-- MealTrack: all schema migrations in one file, for pasting into the Supabase SQL Editor.
-- Generated by scripts/build-setup-sql.mjs from supabase/migrations (excluding the cron migration;
-- run that separately after setting the Vault secrets). Run on a NEW project only.

-- ==== supabase/migrations/20261029000001_schema.sql ====
-- MealTrack core schema: households, membership, invites and sparse meal overrides.
-- Default meal states are NOT stored; only explicit user changes live in meal_overrides.

-- ---------------------------------------------------------------------------
-- Households
-- ---------------------------------------------------------------------------
create table public.households (
  id          uuid primary key default gen_random_uuid(),
  name        text not null check (char_length(btrim(name)) between 1 and 80),
  timezone    text not null default 'Asia/Kolkata',
  created_by  uuid references auth.users (id) on delete set null,
  created_at  timestamptz not null default now()
);

comment on column public.households.timezone is
  'IANA timezone used for "today", reports and the 10 PM reminder.';

create function public.validate_household_timezone()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  -- Raises invalid_parameter_value for unknown zone names.
  perform now() at time zone new.timezone;
  return new;
exception when others then
  raise exception 'Unknown timezone: %', new.timezone using errcode = '22023';
end;
$$;

create trigger households_validate_timezone
  before insert or update of timezone on public.households
  for each row execute function public.validate_household_timezone();

-- ---------------------------------------------------------------------------
-- Members (one household per user)
-- ---------------------------------------------------------------------------
create table public.household_members (
  household_id  uuid not null references public.households (id) on delete cascade,
  user_id       uuid not null references auth.users (id) on delete cascade,
  role          text not null default 'member' check (role in ('admin', 'member')),
  display_name  text not null check (char_length(btrim(display_name)) between 1 and 60),
  joined_at     timestamptz not null default now(),
  primary key (household_id, user_id),
  constraint household_members_one_household unique (user_id)
);

-- ---------------------------------------------------------------------------
-- Invitations
-- ---------------------------------------------------------------------------
create table public.household_invites (
  id            uuid primary key default gen_random_uuid(),
  household_id  uuid not null references public.households (id) on delete cascade,
  email         text not null check (email = lower(btrim(email)) and email ~ '^[^@\s]+@[^@\s]+\.[^@\s]+$'),
  role          text not null default 'member' check (role in ('admin', 'member')),
  token         text not null unique
                  default replace(gen_random_uuid()::text, '-', '') || replace(gen_random_uuid()::text, '-', ''),
  invited_by    uuid references auth.users (id) on delete set null,
  created_at    timestamptz not null default now(),
  expires_at    timestamptz not null default now() + interval '7 days',
  accepted_at   timestamptz,
  accepted_by   uuid references auth.users (id) on delete set null,
  revoked_at    timestamptz
);

create index household_invites_household_idx on public.household_invites (household_id);

-- ---------------------------------------------------------------------------
-- Meal overrides (sparse; one row per explicitly changed meal)
-- ---------------------------------------------------------------------------
create table public.meal_overrides (
  id                    uuid primary key default gen_random_uuid(),
  household_id          uuid not null references public.households (id) on delete cascade,
  meal_date             date not null,
  meal_period           text not null check (meal_period in ('lunch', 'dinner')),
  delivery_status       text not null check (delivery_status in ('delivered', 'not_received')),
  main_dish             text check (main_dish in ('egg', 'chicken')),
  extra_curry_received  boolean,
  created_by            uuid references auth.users (id) on delete set null,
  updated_by            uuid references auth.users (id) on delete set null,
  created_at            timestamptz not null default now(),
  updated_at            timestamptz not null default now(),
  version               integer not null default 1,

  constraint meal_overrides_household_date_period_key unique (household_id, meal_date, meal_period),
  -- Sunday (ISO weekday 7) has no scheduled meals.
  constraint meal_overrides_not_sunday check (extract(isodow from meal_date) <> 7),
  -- Non-veg days (Tue=2, Wed=3, Fri=5) need both non-veg fields; veg days must not have them.
  constraint meal_overrides_shape check (
    case
      when extract(isodow from meal_date) in (2, 3, 5)
        then main_dish is not null and extra_curry_received is not null
      else main_dish is null and extra_curry_received is null
    end
  )
);

comment on table public.meal_overrides is
  'Explicit changes only. A meal with no row uses the schedule default (delivered; chicken + extra curry on non-veg days).';

-- Stamp authorship/version server-side; identity columns cannot be changed by updates.
create function public.meal_overrides_stamp()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    new.created_by := coalesce(auth.uid(), new.created_by);
    new.updated_by := new.created_by;
    new.created_at := now();
    new.updated_at := now();
    new.version := 1;
  else
    new.id := old.id;
    new.household_id := old.household_id;
    new.meal_date := old.meal_date;
    new.meal_period := old.meal_period;
    new.created_by := old.created_by;
    new.created_at := old.created_at;
    new.updated_by := coalesce(auth.uid(), new.updated_by);
    new.updated_at := now();
    new.version := old.version + 1;
  end if;
  return new;
end;
$$;

create trigger meal_overrides_stamp
  before insert or update on public.meal_overrides
  for each row execute function public.meal_overrides_stamp();


-- ==== supabase/migrations/20261029000002_rls.sql ====
-- Row Level Security. Every exposed table has RLS enabled; access is scoped to
-- the caller's household, verified against household_members (never trusting a
-- household id sent by the client).

-- Membership helpers. SECURITY DEFINER avoids recursive policy evaluation on
-- household_members; they only ever answer questions about auth.uid().
create function public.is_household_member(hid uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.household_members m
    where m.household_id = hid and m.user_id = auth.uid()
  );
$$;

create function public.is_household_admin(hid uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.household_members m
    where m.household_id = hid and m.user_id = auth.uid() and m.role = 'admin'
  );
$$;

create function public.my_household_id()
returns uuid
language sql
stable
security definer
set search_path = ''
as $$
  select m.household_id from public.household_members m where m.user_id = auth.uid();
$$;

-- ---------------------------------------------------------------------------
-- Privileges: the app requires sign-in, so anon gets nothing.
-- ---------------------------------------------------------------------------
revoke all on public.households, public.household_members, public.household_invites, public.meal_overrides
  from anon, authenticated;

grant select, update (name, timezone) on public.households to authenticated;
grant select, update (display_name), delete on public.household_members to authenticated;
grant select, insert, update (revoked_at) on public.household_invites to authenticated;
grant select, insert, update, delete on public.meal_overrides to authenticated;

alter table public.households enable row level security;
alter table public.household_members enable row level security;
alter table public.household_invites enable row level security;
alter table public.meal_overrides enable row level security;

-- households --------------------------------------------------------------
create policy "members read their household"
  on public.households for select to authenticated
  using (public.is_household_member(id));

create policy "admins update their household"
  on public.households for update to authenticated
  using (public.is_household_admin(id))
  with check (public.is_household_admin(id));

-- household_members -------------------------------------------------------
create policy "members read fellow members"
  on public.household_members for select to authenticated
  using (public.is_household_member(household_id));

create policy "members update their own display name"
  on public.household_members for update to authenticated
  using (user_id = auth.uid())
  with check (user_id = auth.uid());

create policy "admins remove other members"
  on public.household_members for delete to authenticated
  using (public.is_household_admin(household_id) and user_id <> auth.uid());

-- household_invites (admin only; invitees use the accept_invite RPC) ------
create policy "admins read invites"
  on public.household_invites for select to authenticated
  using (public.is_household_admin(household_id));

create policy "admins create invites"
  on public.household_invites for insert to authenticated
  with check (public.is_household_admin(household_id) and invited_by = auth.uid());

create policy "admins revoke invites"
  on public.household_invites for update to authenticated
  using (public.is_household_admin(household_id))
  with check (public.is_household_admin(household_id));

-- meal_overrides ----------------------------------------------------------
create policy "members read meals"
  on public.meal_overrides for select to authenticated
  using (public.is_household_member(household_id));

create policy "members add meals"
  on public.meal_overrides for insert to authenticated
  with check (public.is_household_member(household_id));

create policy "members change meals"
  on public.meal_overrides for update to authenticated
  using (public.is_household_member(household_id))
  with check (public.is_household_member(household_id));

create policy "members delete meals"
  on public.meal_overrides for delete to authenticated
  using (public.is_household_member(household_id));

revoke execute on function public.is_household_member(uuid), public.is_household_admin(uuid), public.my_household_id()
  from public, anon;
grant execute on function public.is_household_member(uuid), public.is_household_admin(uuid), public.my_household_id()
  to authenticated;


-- ==== supabase/migrations/20261029000003_rpc.sql ====
-- Household setup, invitations and the conflict-aware meal save.

-- ---------------------------------------------------------------------------
-- create_household: the caller becomes the first administrator.
-- ---------------------------------------------------------------------------
create function public.create_household(p_name text, p_display_name text, p_timezone text default 'Asia/Kolkata')
returns public.households
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_household public.households;
begin
  if v_uid is null then
    raise exception 'Not authenticated' using errcode = '28000';
  end if;
  if exists (select 1 from public.household_members where user_id = v_uid) then
    raise exception 'You already belong to a household' using errcode = 'P0001';
  end if;

  insert into public.households (name, timezone, created_by)
  values (btrim(p_name), coalesce(nullif(btrim(p_timezone), ''), 'Asia/Kolkata'), v_uid)
  returning * into v_household;

  insert into public.household_members (household_id, user_id, role, display_name)
  values (v_household.id, v_uid, 'admin', btrim(p_display_name));

  return v_household;
end;
$$;

-- ---------------------------------------------------------------------------
-- create_invite: admins invite an email address. Returns the row incl. token.
-- ---------------------------------------------------------------------------
create function public.create_invite(p_email text, p_role text default 'member')
returns public.household_invites
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_household uuid := public.my_household_id();
  v_invite public.household_invites;
begin
  if v_household is null or not public.is_household_admin(v_household) then
    raise exception 'Only household administrators can invite members' using errcode = '42501';
  end if;

  -- Revoke any earlier pending invite for the same address.
  update public.household_invites
     set revoked_at = now()
   where household_id = v_household
     and email = lower(btrim(p_email))
     and accepted_at is null
     and revoked_at is null;

  insert into public.household_invites (household_id, email, role, invited_by)
  values (v_household, lower(btrim(p_email)), coalesce(p_role, 'member'), auth.uid())
  returning * into v_invite;

  return v_invite;
end;
$$;

-- ---------------------------------------------------------------------------
-- get_invite: lets an invitee preview an invite by token before accepting.
-- ---------------------------------------------------------------------------
create function public.get_invite(p_token text)
returns table (household_name text, email text, role text, expires_at timestamptz, status text)
language sql
stable
security definer
set search_path = ''
as $$
  select h.name,
         i.email,
         i.role,
         i.expires_at,
         case
           when i.revoked_at is not null then 'revoked'
           when i.accepted_at is not null then 'accepted'
           when i.expires_at < now() then 'expired'
           else 'pending'
         end
    from public.household_invites i
    join public.households h on h.id = i.household_id
   where i.token = p_token
     and auth.uid() is not null;
$$;

-- ---------------------------------------------------------------------------
-- accept_invite: validates token, expiry and that the signed-in email matches.
-- ---------------------------------------------------------------------------
create function public.accept_invite(p_token text, p_display_name text)
returns public.household_members
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_email text := lower(coalesce(auth.jwt() ->> 'email', ''));
  v_invite public.household_invites;
  v_member public.household_members;
begin
  if v_uid is null then
    raise exception 'Not authenticated' using errcode = '28000';
  end if;

  select * into v_invite from public.household_invites where token = p_token for update;
  if not found then
    raise exception 'This invite link is not valid' using errcode = 'P0002';
  end if;
  if v_invite.revoked_at is not null then
    raise exception 'This invite has been revoked' using errcode = 'P0001';
  end if;
  if v_invite.accepted_at is not null then
    raise exception 'This invite has already been used' using errcode = 'P0001';
  end if;
  if v_invite.expires_at < now() then
    raise exception 'This invite has expired; ask your administrator for a new one' using errcode = 'P0001';
  end if;
  if v_invite.email <> v_email then
    raise exception 'This invite was sent to a different email address' using errcode = '42501';
  end if;
  if exists (select 1 from public.household_members where user_id = v_uid) then
    raise exception 'You already belong to a household' using errcode = 'P0001';
  end if;

  insert into public.household_members (household_id, user_id, role, display_name)
  values (v_invite.household_id, v_uid, v_invite.role, btrim(p_display_name))
  returning * into v_member;

  update public.household_invites
     set accepted_at = now(), accepted_by = v_uid
   where id = v_invite.id;

  return v_member;
end;
$$;

-- ---------------------------------------------------------------------------
-- set_member_role: admins promote/demote; at least one admin must remain.
-- ---------------------------------------------------------------------------
create function public.set_member_role(p_user_id uuid, p_role text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_household uuid := public.my_household_id();
begin
  if v_household is null or not public.is_household_admin(v_household) then
    raise exception 'Only household administrators can change roles' using errcode = '42501';
  end if;
  if p_role not in ('admin', 'member') then
    raise exception 'Invalid role' using errcode = '22023';
  end if;
  if p_role = 'member' and not exists (
    select 1 from public.household_members
     where household_id = v_household and role = 'admin' and user_id <> p_user_id
  ) then
    raise exception 'A household needs at least one administrator' using errcode = 'P0001';
  end if;

  update public.household_members
     set role = p_role
   where household_id = v_household and user_id = p_user_id;
  if not found then
    raise exception 'Member not found' using errcode = 'P0002';
  end if;
end;
$$;

-- ---------------------------------------------------------------------------
-- save_meal_override: the single write path for meals.
--
-- Optimistic concurrency: the client sends the version it last saw
-- (null = "I saw no override, i.e. the default"). If the stored state has
-- moved on, nothing is written and the current row is returned as a conflict.
-- Saving values equal to the schedule default deletes the override.
-- Saving values identical to what is stored is a no-op ("unchanged"), which
-- makes offline replays idempotent.
--
-- Returns {"status": "saved" | "deleted" | "unchanged" | "conflict", "row": <row or null>}.
-- ---------------------------------------------------------------------------
create function public.save_meal_override(
  p_date date,
  p_period text,
  p_delivery_status text,
  p_main_dish text,
  p_extra_curry boolean,
  p_expected_version integer
)
returns jsonb
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_household uuid := public.my_household_id();
  v_dow int := extract(isodow from p_date);
  v_nonveg boolean := extract(isodow from p_date) in (2, 3, 5);
  v_is_default boolean;
  v_row public.meal_overrides;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated' using errcode = '28000';
  end if;
  if v_household is null then
    raise exception 'You are not a member of a household' using errcode = '42501';
  end if;
  if v_dow = 7 then
    raise exception 'No meals are scheduled on Sundays' using errcode = '22023';
  end if;
  if p_period not in ('lunch', 'dinner') then
    raise exception 'Invalid meal period' using errcode = '22023';
  end if;
  if p_delivery_status not in ('delivered', 'not_received') then
    raise exception 'Invalid delivery status' using errcode = '22023';
  end if;

  if v_nonveg then
    if p_main_dish is null or p_extra_curry is null then
      raise exception 'Main dish and extra curry status are required on non-veg days' using errcode = '22023';
    end if;
  else
    p_main_dish := null;
    p_extra_curry := null;
  end if;

  v_is_default := p_delivery_status = 'delivered'
                  and (not v_nonveg or (p_main_dish = 'chicken' and p_extra_curry));

  select * into v_row
    from public.meal_overrides
   where household_id = v_household and meal_date = p_date and meal_period = p_period
   for update;

  if not found then
    if v_is_default then
      return jsonb_build_object('status', 'unchanged', 'row', null);
    end if;
    if p_expected_version is not null then
      -- The override the client saw was removed by someone else.
      return jsonb_build_object('status', 'conflict', 'row', null);
    end if;

    insert into public.meal_overrides (household_id, meal_date, meal_period, delivery_status, main_dish, extra_curry_received)
    values (v_household, p_date, p_period, p_delivery_status, p_main_dish, p_extra_curry)
    on conflict (household_id, meal_date, meal_period) do nothing
    returning * into v_row;

    if v_row.id is null then
      -- Lost an insert race; report the winner instead of overwriting it.
      select * into v_row from public.meal_overrides
       where household_id = v_household and meal_date = p_date and meal_period = p_period;
      return jsonb_build_object('status', 'conflict', 'row', to_jsonb(v_row));
    end if;
    return jsonb_build_object('status', 'saved', 'row', to_jsonb(v_row));
  end if;

  if v_row.delivery_status = p_delivery_status
     and v_row.main_dish is not distinct from p_main_dish
     and v_row.extra_curry_received is not distinct from p_extra_curry then
    return jsonb_build_object('status', 'unchanged', 'row', to_jsonb(v_row));
  end if;

  if p_expected_version is distinct from v_row.version then
    return jsonb_build_object('status', 'conflict', 'row', to_jsonb(v_row));
  end if;

  if v_is_default then
    delete from public.meal_overrides where id = v_row.id;
    return jsonb_build_object('status', 'deleted', 'row', null);
  end if;

  update public.meal_overrides
     set delivery_status = p_delivery_status,
         main_dish = p_main_dish,
         extra_curry_received = p_extra_curry
   where id = v_row.id
  returning * into v_row;

  return jsonb_build_object('status', 'saved', 'row', to_jsonb(v_row));
end;
$$;

revoke execute on function
  public.create_household(text, text, text),
  public.create_invite(text, text),
  public.get_invite(text),
  public.accept_invite(text, text),
  public.set_member_role(uuid, text),
  public.save_meal_override(date, text, text, text, boolean, integer)
  from public, anon;

grant execute on function
  public.create_household(text, text, text),
  public.create_invite(text, text),
  public.get_invite(text),
  public.accept_invite(text, text),
  public.set_member_role(uuid, text),
  public.save_meal_override(date, text, text, text, boolean, integer)
  to authenticated;


-- ==== supabase/migrations/20261029000004_notifications.sql ====
-- Reminder preferences, Web Push subscriptions and the delivery log.
-- Push private keys never live in the database; they are Edge Function secrets.

create table public.notification_preferences (
  user_id            uuid primary key references auth.users (id) on delete cascade,
  household_id       uuid not null references public.households (id) on delete cascade,
  reminders_enabled  boolean not null default false,
  updated_at         timestamptz not null default now()
);

create table public.push_subscriptions (
  id               uuid primary key default gen_random_uuid(),
  user_id          uuid not null references auth.users (id) on delete cascade,
  household_id     uuid not null references public.households (id) on delete cascade,
  endpoint         text not null unique check (endpoint ~ '^https://'),
  p256dh           text not null,
  auth             text not null,
  user_agent       text,
  created_at       timestamptz not null default now(),
  last_success_at  timestamptz,
  disabled_at      timestamptz
);

create index push_subscriptions_user_idx on public.push_subscriptions (user_id) where disabled_at is null;

create table public.notification_log (
  id               uuid primary key default gen_random_uuid(),
  household_id     uuid not null references public.households (id) on delete cascade,
  user_id          uuid references auth.users (id) on delete cascade,
  subscription_id  uuid references public.push_subscriptions (id) on delete set null,
  kind             text not null default 'daily' check (kind in ('daily', 'test')),
  reminder_date    date not null,
  status           text not null default 'pending' check (status in ('pending', 'sent', 'failed', 'gone')),
  attempts         integer not null default 1,
  http_status      integer,
  error            text,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now()
);

-- One daily reminder per device per household-local date.
create unique index notification_log_daily_once
  on public.notification_log (subscription_id, reminder_date)
  where kind = 'daily';

create index notification_log_household_idx on public.notification_log (household_id, created_at desc);

-- ---------------------------------------------------------------------------
-- RLS: users manage only their own preferences/subscriptions. The log is
-- written exclusively by the Edge Function using the service role.
-- ---------------------------------------------------------------------------
revoke all on public.notification_preferences, public.push_subscriptions, public.notification_log
  from anon, authenticated;

grant select, insert, update (reminders_enabled, updated_at) on public.notification_preferences to authenticated;
grant select, delete on public.push_subscriptions to authenticated;
grant select on public.notification_log to authenticated;

alter table public.notification_preferences enable row level security;
alter table public.push_subscriptions enable row level security;
alter table public.notification_log enable row level security;

create policy "users read own preferences"
  on public.notification_preferences for select to authenticated
  using (user_id = auth.uid());

create policy "users create own preferences"
  on public.notification_preferences for insert to authenticated
  with check (user_id = auth.uid() and public.is_household_member(household_id));

create policy "users change own preferences"
  on public.notification_preferences for update to authenticated
  using (user_id = auth.uid())
  with check (user_id = auth.uid() and public.is_household_member(household_id));

create policy "users read own subscriptions"
  on public.push_subscriptions for select to authenticated
  using (user_id = auth.uid());

create policy "users remove own subscriptions"
  on public.push_subscriptions for delete to authenticated
  using (user_id = auth.uid());

create policy "users read own notification log"
  on public.notification_log for select to authenticated
  using (user_id = auth.uid());

-- ---------------------------------------------------------------------------
-- register_push_subscription: a browser endpoint identifies one device, so it
-- is (re)assigned to whoever subscribed on it most recently. This keeps one
-- row per device and prevents duplicate notifications to a shared phone.
-- ---------------------------------------------------------------------------
create function public.register_push_subscription(
  p_endpoint text,
  p_p256dh text,
  p_auth text,
  p_user_agent text default null
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_household uuid := public.my_household_id();
  v_id uuid;
begin
  if v_uid is null then
    raise exception 'Not authenticated' using errcode = '28000';
  end if;
  if v_household is null then
    raise exception 'You are not a member of a household' using errcode = '42501';
  end if;

  insert into public.push_subscriptions (user_id, household_id, endpoint, p256dh, auth, user_agent)
  values (v_uid, v_household, p_endpoint, p_p256dh, p_auth, left(p_user_agent, 300))
  on conflict (endpoint) do update
    set user_id = excluded.user_id,
        household_id = excluded.household_id,
        p256dh = excluded.p256dh,
        auth = excluded.auth,
        user_agent = excluded.user_agent,
        disabled_at = null
  returning id into v_id;

  insert into public.notification_preferences (user_id, household_id, reminders_enabled)
  values (v_uid, v_household, true)
  on conflict (user_id) do update set reminders_enabled = true, household_id = excluded.household_id, updated_at = now();

  return v_id;
end;
$$;

revoke execute on function public.register_push_subscription(text, text, text, text) from public, anon;
grant execute on function public.register_push_subscription(text, text, text, text) to authenticated;

-- ---------------------------------------------------------------------------
-- claim_daily_reminder (service role only): atomically reserves the right to
-- send one device its reminder for a local date. Returns the log id when the
-- caller should send, or null when it was already sent (or is in flight).
-- A failed attempt may be retried on a later cron tick, up to 3 attempts.
-- ---------------------------------------------------------------------------
create function public.claim_daily_reminder(
  p_household_id uuid,
  p_user_id uuid,
  p_subscription_id uuid,
  p_reminder_date date
)
returns uuid
language sql
security invoker
set search_path = ''
as $$
  insert into public.notification_log (household_id, user_id, subscription_id, kind, reminder_date, status)
  values (p_household_id, p_user_id, p_subscription_id, 'daily', p_reminder_date, 'pending')
  on conflict (subscription_id, reminder_date) where kind = 'daily'
  do update set status = 'pending', attempts = public.notification_log.attempts + 1, error = null, updated_at = now()
     where public.notification_log.status = 'failed' and public.notification_log.attempts < 3
  returning id;
$$;

revoke execute on function public.claim_daily_reminder(uuid, uuid, uuid, date) from public, anon, authenticated;
grant execute on function public.claim_daily_reminder(uuid, uuid, uuid, date) to service_role;

-- Realtime: broadcast meal changes (RLS still applies to subscribers).
alter publication supabase_realtime add table public.meal_overrides;


-- ==== supabase/migrations/20261029000006_family_pin.sql ====
-- Family PIN access: no email accounts. Each phone signs in anonymously
-- (Supabase anonymous auth) and joins the single family household by entering
-- the shared PIN. Membership then drives the existing RLS policies unchanged.
--
-- PIN security:
--   * stored only as a bcrypt hash (pgcrypto), never readable by clients;
--   * 6–10 digits;
--   * all PIN checks share a global limit of 10 wrong attempts per 15 minutes.

create extension if not exists pgcrypto with schema extensions;

alter table public.households add column if not exists pin_hash text;

-- Clients may read every household column except the PIN hash.
revoke select on public.households from authenticated;
grant select (id, name, timezone, created_by, created_at) on public.households to authenticated;

create table if not exists public.family_pin_attempts (
  id          bigint generated always as identity primary key,
  user_id     uuid,
  success     boolean not null,
  created_at  timestamptz not null default now()
);
create index if not exists family_pin_attempts_recent_idx on public.family_pin_attempts (created_at) where not success;

-- No client access at all (RLS on, no policies, no grants).
alter table public.family_pin_attempts enable row level security;
revoke all on public.family_pin_attempts from anon, authenticated;

-- ---------------------------------------------------------------------------
-- Internal helpers (not callable by clients)
-- ---------------------------------------------------------------------------
create or replace function public._pin_failures_recent()
returns integer
language sql
stable
security definer
set search_path = ''
as $$
  select count(*)::int from public.family_pin_attempts
   where not success and created_at > now() - interval '15 minutes';
$$;

create or replace function public._validate_pin(p_pin text)
returns void
language plpgsql
immutable
set search_path = ''
as $$
begin
  if p_pin is null or p_pin !~ '^[0-9]{6,10}$' then
    raise exception 'The family PIN must be 6 to 10 digits' using errcode = '22023';
  end if;
end;
$$;

revoke execute on function public._pin_failures_recent(), public._validate_pin(text) from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- mealtrack_status: lets a new phone know whether to show "Set up" or
-- "Enter PIN". Reveals nothing beyond that.
-- ---------------------------------------------------------------------------
create or replace function public.mealtrack_status()
returns text
language sql
stable
security definer
set search_path = ''
as $$
  select case
    when not exists (select 1 from public.households) then 'not_set_up'
    when not exists (select 1 from public.households where pin_hash is not null) then 'needs_pin'
    else 'ready'
  end;
$$;

-- ---------------------------------------------------------------------------
-- setup_household: first-time setup. Only possible while no household exists.
-- ---------------------------------------------------------------------------
create or replace function public.setup_household(p_name text, p_display_name text, p_pin text, p_timezone text default 'Asia/Kolkata')
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_id uuid;
begin
  if v_uid is null then
    raise exception 'Not authenticated' using errcode = '28000';
  end if;
  perform public._validate_pin(p_pin);
  perform pg_advisory_xact_lock(hashtext('mealtrack.setup'));
  if exists (select 1 from public.households) then
    raise exception 'MealTrack is already set up. Enter the family PIN to join.' using errcode = 'P0001';
  end if;

  insert into public.households (name, timezone, created_by, pin_hash)
  values (btrim(p_name), coalesce(nullif(btrim(p_timezone), ''), 'Asia/Kolkata'), v_uid,
          extensions.crypt(p_pin, extensions.gen_salt('bf', 8)))
  returning id into v_id;

  insert into public.household_members (household_id, user_id, role, display_name)
  values (v_id, v_uid, 'admin', btrim(p_display_name));

  return jsonb_build_object('id', v_id);
end;
$$;

-- ---------------------------------------------------------------------------
-- join_with_pin: adds this phone (anonymous user) to the family.
-- Returns {"ok": true} or {"ok": false, "error": "wrong_pin"|"locked", "attempts_left": n}.
-- Wrong attempts are returned (not raised) so the attempt record is committed.
-- ---------------------------------------------------------------------------
create or replace function public.join_with_pin(p_pin text, p_display_name text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_failures int;
  v_household uuid;
begin
  if v_uid is null then
    raise exception 'Not authenticated' using errcode = '28000';
  end if;
  if exists (select 1 from public.household_members where user_id = v_uid) then
    return jsonb_build_object('ok', true);
  end if;
  if char_length(btrim(coalesce(p_display_name, ''))) not between 1 and 60 then
    raise exception 'Please enter a name for this phone' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtext('mealtrack.pin'));
  v_failures := public._pin_failures_recent();
  if v_failures >= 10 then
    return jsonb_build_object('ok', false, 'error', 'locked');
  end if;

  select id into v_household
    from public.households
   where pin_hash is not null and pin_hash = extensions.crypt(coalesce(p_pin, ''), pin_hash)
   limit 1;

  if v_household is null then
    insert into public.family_pin_attempts (user_id, success) values (v_uid, false);
    return jsonb_build_object('ok', false, 'error', 'wrong_pin', 'attempts_left', greatest(0, 9 - v_failures));
  end if;

  insert into public.family_pin_attempts (user_id, success) values (v_uid, true);
  -- Every family phone has equal rights.
  insert into public.household_members (household_id, user_id, role, display_name)
  values (v_household, v_uid, 'admin', btrim(p_display_name));
  return jsonb_build_object('ok', true);
end;
$$;

-- ---------------------------------------------------------------------------
-- verify_family_pin: app-lock fallback when fingerprint/Face ID is unavailable.
-- ---------------------------------------------------------------------------
create or replace function public.verify_family_pin(p_pin text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_household uuid := public.my_household_id();
  v_failures int;
  v_ok boolean;
begin
  if v_household is null then
    raise exception 'This phone is not part of the family yet' using errcode = '42501';
  end if;
  perform pg_advisory_xact_lock(hashtext('mealtrack.pin'));
  v_failures := public._pin_failures_recent();
  if v_failures >= 10 then
    return jsonb_build_object('ok', false, 'error', 'locked');
  end if;
  select pin_hash = extensions.crypt(coalesce(p_pin, ''), pin_hash) into v_ok
    from public.households where id = v_household;
  insert into public.family_pin_attempts (user_id, success) values (v_uid, coalesce(v_ok, false));
  if coalesce(v_ok, false) then
    return jsonb_build_object('ok', true);
  end if;
  return jsonb_build_object('ok', false, 'error', 'wrong_pin', 'attempts_left', greatest(0, 9 - v_failures));
end;
$$;

-- ---------------------------------------------------------------------------
-- change_family_pin: any family phone, given the current PIN. Phones that
-- already joined stay joined; new phones need the new PIN.
-- ---------------------------------------------------------------------------
create or replace function public.change_family_pin(p_current text, p_new text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_check jsonb;
begin
  perform public._validate_pin(p_new);
  v_check := public.verify_family_pin(p_current);
  if not (v_check ->> 'ok')::boolean then
    return v_check;
  end if;
  update public.households
     set pin_hash = extensions.crypt(p_new, extensions.gen_salt('bf', 8))
   where id = public.my_household_id();
  return jsonb_build_object('ok', true);
end;
$$;

-- ---------------------------------------------------------------------------
-- leave_household: "Remove this phone" — deletes this phone's membership,
-- reminder settings and push registration.
-- ---------------------------------------------------------------------------
create or replace function public.leave_household()
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    raise exception 'Not authenticated' using errcode = '28000';
  end if;
  delete from public.push_subscriptions where user_id = v_uid;
  delete from public.notification_preferences where user_id = v_uid;
  delete from public.household_members where user_id = v_uid;
end;
$$;

-- ---------------------------------------------------------------------------
-- admin_set_family_pin: for the Supabase SQL Editor only (e.g. a household
-- created before PINs existed, or a forgotten PIN). Not callable by clients.
--   select public.admin_set_family_pin('123456');
-- ---------------------------------------------------------------------------
create or replace function public.admin_set_family_pin(p_pin text)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_count int;
begin
  perform public._validate_pin(p_pin);
  update public.households set pin_hash = extensions.crypt(p_pin, extensions.gen_salt('bf', 8));
  get diagnostics v_count = row_count;
  delete from public.family_pin_attempts;
  return v_count;
end;
$$;

-- Household creation now only happens through setup_household (single family).
revoke execute on function public.create_household(text, text, text) from authenticated;

revoke execute on function
  public.mealtrack_status(),
  public.setup_household(text, text, text, text),
  public.join_with_pin(text, text),
  public.verify_family_pin(text),
  public.change_family_pin(text, text),
  public.leave_household(),
  public.admin_set_family_pin(text)
  from public, anon;

grant execute on function
  public.mealtrack_status(),
  public.setup_household(text, text, text, text),
  public.join_with_pin(text, text),
  public.verify_family_pin(text),
  public.change_family_pin(text, text),
  public.leave_household()
  to authenticated;

revoke execute on function public.admin_set_family_pin(text) from authenticated;


-- ==== supabase/migrations/20261029000007_not_delivered_clears_dish.sql ====
-- A meal that was not delivered has no main dish and no extra curries.
-- Non-veg rows therefore carry main_dish / extra_curry_received only when the
-- meal was delivered; not-received rows store NULL for both.

-- Drop the old rule first: it requires dish/curry on every non-veg row, so
-- clearing them while it is still in place would be rejected.
alter table public.meal_overrides drop constraint if exists meal_overrides_shape;

update public.meal_overrides
   set main_dish = null, extra_curry_received = null
 where delivery_status = 'not_received'
   and (main_dish is not null or extra_curry_received is not null);

alter table public.meal_overrides add constraint meal_overrides_shape check (
  case
    when extract(isodow from meal_date) in (2, 3, 5) and delivery_status = 'delivered'
      then main_dish is not null and extra_curry_received is not null
    else main_dish is null and extra_curry_received is null
  end
);

create or replace function public.save_meal_override(
  p_date date,
  p_period text,
  p_delivery_status text,
  p_main_dish text,
  p_extra_curry boolean,
  p_expected_version integer
)
returns jsonb
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_household uuid := public.my_household_id();
  v_dow int := extract(isodow from p_date);
  v_nonveg boolean := extract(isodow from p_date) in (2, 3, 5);
  v_is_default boolean;
  v_row public.meal_overrides;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated' using errcode = '28000';
  end if;
  if v_household is null then
    raise exception 'You are not a member of a household' using errcode = '42501';
  end if;
  if v_dow = 7 then
    raise exception 'No meals are scheduled on Sundays' using errcode = '22023';
  end if;
  if p_period not in ('lunch', 'dinner') then
    raise exception 'Invalid meal period' using errcode = '22023';
  end if;
  if p_delivery_status not in ('delivered', 'not_received') then
    raise exception 'Invalid delivery status' using errcode = '22023';
  end if;

  if v_nonveg and p_delivery_status = 'delivered' then
    if p_main_dish is null or p_extra_curry is null then
      raise exception 'Main dish and extra curry status are required for a delivered non-veg meal' using errcode = '22023';
    end if;
  else
    -- Veg meals, and meals that were not delivered, have no dish/curry details.
    p_main_dish := null;
    p_extra_curry := null;
  end if;

  v_is_default := p_delivery_status = 'delivered'
                  and (not v_nonveg or (p_main_dish = 'chicken' and p_extra_curry));

  select * into v_row
    from public.meal_overrides
   where household_id = v_household and meal_date = p_date and meal_period = p_period
   for update;

  if not found then
    if v_is_default then
      return jsonb_build_object('status', 'unchanged', 'row', null);
    end if;
    if p_expected_version is not null then
      return jsonb_build_object('status', 'conflict', 'row', null);
    end if;

    insert into public.meal_overrides (household_id, meal_date, meal_period, delivery_status, main_dish, extra_curry_received)
    values (v_household, p_date, p_period, p_delivery_status, p_main_dish, p_extra_curry)
    on conflict (household_id, meal_date, meal_period) do nothing
    returning * into v_row;

    if v_row.id is null then
      select * into v_row from public.meal_overrides
       where household_id = v_household and meal_date = p_date and meal_period = p_period;
      return jsonb_build_object('status', 'conflict', 'row', to_jsonb(v_row));
    end if;
    return jsonb_build_object('status', 'saved', 'row', to_jsonb(v_row));
  end if;

  if v_row.delivery_status = p_delivery_status
     and v_row.main_dish is not distinct from p_main_dish
     and v_row.extra_curry_received is not distinct from p_extra_curry then
    return jsonb_build_object('status', 'unchanged', 'row', to_jsonb(v_row));
  end if;

  if p_expected_version is distinct from v_row.version then
    return jsonb_build_object('status', 'conflict', 'row', to_jsonb(v_row));
  end if;

  if v_is_default then
    delete from public.meal_overrides where id = v_row.id;
    return jsonb_build_object('status', 'deleted', 'row', null);
  end if;

  update public.meal_overrides
     set delivery_status = p_delivery_status,
         main_dish = p_main_dish,
         extra_curry_received = p_extra_curry
   where id = v_row.id
  returning * into v_row;

  return jsonb_build_object('status', 'saved', 'row', to_jsonb(v_row));
end;
$$;


-- ==== supabase/migrations/20261029000008_admin_approval.sql ====
-- Sign-in with name + PIN, then admin approval.
-- A correct PIN only creates a PENDING request; the person can see and edit
-- nothing until an admin approves them. Only admins manage people and the PIN.

alter table public.household_members
  add column if not exists status text not null default 'approved' check (status in ('pending', 'approved')),
  add column if not exists approved_by uuid references auth.users (id) on delete set null,
  add column if not exists approved_at timestamptz;

-- Access helpers now require an APPROVED membership. Every RLS policy and
-- RPC that uses them therefore excludes pending people automatically.
create or replace function public.is_household_member(hid uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.household_members m
    where m.household_id = hid and m.user_id = auth.uid() and m.status = 'approved'
  );
$$;

create or replace function public.is_household_admin(hid uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.household_members m
    where m.household_id = hid and m.user_id = auth.uid() and m.role = 'admin' and m.status = 'approved'
  );
$$;

create or replace function public.my_household_id()
returns uuid
language sql
stable
security definer
set search_path = ''
as $$
  select m.household_id from public.household_members m where m.user_id = auth.uid() and m.status = 'approved';
$$;

-- People can always see their own row (to show "waiting for approval").
drop policy if exists "users read own membership" on public.household_members;
create policy "users read own membership"
  on public.household_members for select to authenticated
  using (user_id = auth.uid());

-- Only admins remove people (through remove_member, which also stops reminders).
drop policy if exists "admins remove other members" on public.household_members;
revoke delete on public.household_members from authenticated;

-- ---------------------------------------------------------------------------
-- join_with_pin (sign in): a correct PIN creates a pending request.
-- Returns {"ok": true, "status": "pending"|"approved"} or a PIN error.
-- ---------------------------------------------------------------------------
create or replace function public.join_with_pin(p_pin text, p_display_name text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_existing text;
  v_failures int;
  v_household uuid;
begin
  if v_uid is null then
    raise exception 'Not authenticated' using errcode = '28000';
  end if;
  select status into v_existing from public.household_members where user_id = v_uid;
  if v_existing is not null then
    return jsonb_build_object('ok', true, 'status', v_existing);
  end if;
  if char_length(btrim(coalesce(p_display_name, ''))) not between 1 and 60 then
    raise exception 'Please enter your name' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtext('mealtrack.pin'));
  v_failures := public._pin_failures_recent();
  if v_failures >= 10 then
    return jsonb_build_object('ok', false, 'error', 'locked');
  end if;

  select id into v_household
    from public.households
   where pin_hash is not null and pin_hash = extensions.crypt(coalesce(p_pin, ''), pin_hash)
   limit 1;

  if v_household is null then
    insert into public.family_pin_attempts (user_id, success) values (v_uid, false);
    return jsonb_build_object('ok', false, 'error', 'wrong_pin', 'attempts_left', greatest(0, 9 - v_failures));
  end if;

  insert into public.family_pin_attempts (user_id, success) values (v_uid, true);
  insert into public.household_members (household_id, user_id, role, display_name, status)
  values (v_household, v_uid, 'member', btrim(p_display_name), 'pending');
  return jsonb_build_object('ok', true, 'status', 'pending');
end;
$$;

-- ---------------------------------------------------------------------------
-- Admin actions
-- ---------------------------------------------------------------------------
create or replace function public.approve_member(p_user_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_household uuid := public.my_household_id();
begin
  if v_household is null or not public.is_household_admin(v_household) then
    raise exception 'Only an admin can approve people' using errcode = '42501';
  end if;
  update public.household_members
     set status = 'approved', approved_by = auth.uid(), approved_at = now()
   where household_id = v_household and user_id = p_user_id and status = 'pending';
  if not found then
    raise exception 'That request no longer exists' using errcode = 'P0002';
  end if;
end;
$$;

-- Decline a pending request, or remove an approved person. Also deletes their
-- reminder settings and push registrations so they stop getting reminders.
create or replace function public.remove_member(p_user_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_household uuid := public.my_household_id();
begin
  if v_household is null or not public.is_household_admin(v_household) then
    raise exception 'Only an admin can remove people' using errcode = '42501';
  end if;
  if p_user_id = auth.uid() then
    raise exception 'Use Sign out to remove yourself' using errcode = 'P0001';
  end if;
  if exists (
    select 1 from public.household_members
     where household_id = v_household and user_id = p_user_id and role = 'admin' and status = 'approved'
  ) and not exists (
    select 1 from public.household_members
     where household_id = v_household and role = 'admin' and status = 'approved' and user_id <> p_user_id
  ) then
    raise exception 'MealTrack needs at least one admin' using errcode = 'P0001';
  end if;
  delete from public.push_subscriptions where user_id = p_user_id and household_id = v_household;
  delete from public.notification_preferences where user_id = p_user_id and household_id = v_household;
  delete from public.household_members where household_id = v_household and user_id = p_user_id;
end;
$$;

-- set_member_role: only for approved people; at least one admin must remain.
create or replace function public.set_member_role(p_user_id uuid, p_role text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_household uuid := public.my_household_id();
begin
  if v_household is null or not public.is_household_admin(v_household) then
    raise exception 'Only an admin can change roles' using errcode = '42501';
  end if;
  if p_role not in ('admin', 'member') then
    raise exception 'Invalid role' using errcode = '22023';
  end if;
  if p_role = 'member' and not exists (
    select 1 from public.household_members
     where household_id = v_household and role = 'admin' and status = 'approved' and user_id <> p_user_id
  ) then
    raise exception 'MealTrack needs at least one admin' using errcode = 'P0001';
  end if;
  update public.household_members
     set role = p_role
   where household_id = v_household and user_id = p_user_id and status = 'approved';
  if not found then
    raise exception 'Person not found' using errcode = 'P0002';
  end if;
end;
$$;

-- leave_household (sign out / cancel request): the last admin cannot leave
-- while other people still depend on them.
create or replace function public.leave_household()
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_household uuid;
begin
  if v_uid is null then
    raise exception 'Not authenticated' using errcode = '28000';
  end if;
  select household_id into v_household from public.household_members
   where user_id = v_uid and role = 'admin' and status = 'approved';
  if v_household is not null
     and not exists (select 1 from public.household_members
                      where household_id = v_household and role = 'admin' and status = 'approved' and user_id <> v_uid)
     and exists (select 1 from public.household_members where household_id = v_household and user_id <> v_uid) then
    raise exception 'You are the only admin. Make someone else an admin before signing out.' using errcode = 'P0001';
  end if;
  delete from public.push_subscriptions where user_id = v_uid;
  delete from public.notification_preferences where user_id = v_uid;
  delete from public.household_members where user_id = v_uid;
end;
$$;

-- Only admins may change the PIN.
create or replace function public.change_family_pin(p_current text, p_new text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_check jsonb;
  v_household uuid := public.my_household_id();
begin
  if v_household is null or not public.is_household_admin(v_household) then
    raise exception 'Only an admin can change the PIN' using errcode = '42501';
  end if;
  perform public._validate_pin(p_new);
  v_check := public.verify_family_pin(p_current);
  if not (v_check ->> 'ok')::boolean then
    return v_check;
  end if;
  update public.households
     set pin_hash = extensions.crypt(p_new, extensions.gen_salt('bf', 8))
   where id = v_household;
  return jsonb_build_object('ok', true);
end;
$$;

revoke execute on function public.approve_member(uuid), public.remove_member(uuid) from public, anon;
grant execute on function public.approve_member(uuid), public.remove_member(uuid) to authenticated;


-- ==== supabase/migrations/20261029000009_personal_pins.sql ====
-- Personal PINs replace the shared family PIN.
--   * Each person signs in with their NAME + their OWN PIN.
--   * A new name creates a pending request; an admin approves it ONCE.
--   * A returning person (new phone, reinstall, signed out) with the right
--     PIN is let straight back in with the same role: no approval.
--   * Names are unique per household (case-insensitive).
--   * Wrong PINs: 5 per name per 15 minutes, 30 overall per 15 minutes.

alter table public.household_members add column if not exists pin_hash text;
alter table public.family_pin_attempts add column if not exists name_key text;

create unique index if not exists household_members_name_key
  on public.household_members (household_id, lower(display_name));

-- Members may read each other's rows, but never the PIN hash.
revoke select on public.household_members from authenticated;
grant select (household_id, user_id, role, display_name, joined_at, status, approved_by, approved_at)
  on public.household_members to authenticated;

create or replace function public._validate_pin(p_pin text)
returns void
language plpgsql
immutable
set search_path = ''
as $$
begin
  if p_pin is null or p_pin !~ '^[0-9]{6,10}$' then
    raise exception 'Your PIN must be 6 to 10 digits' using errcode = '22023';
  end if;
end;
$$;

-- Failed attempts for one name, and overall, in the last 15 minutes.
create or replace function public._pin_failures(p_name_key text, out for_name int, out overall int)
language sql
stable
security definer
set search_path = ''
as $$
  select count(*) filter (where name_key = p_name_key)::int, count(*)::int
    from public.family_pin_attempts
   where not success and created_at > now() - interval '15 minutes';
$$;
revoke execute on function public._pin_failures(text) from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- mealtrack_status: 'not_set_up' until the first person sets MealTrack up.
-- ---------------------------------------------------------------------------
create or replace function public.mealtrack_status()
returns text
language sql
stable
security definer
set search_path = ''
as $$
  select case when exists (select 1 from public.households) then 'ready' else 'not_set_up' end;
$$;

-- ---------------------------------------------------------------------------
-- setup_household: the first person (name + their PIN) becomes the admin.
-- ---------------------------------------------------------------------------
create or replace function public.setup_household(p_name text, p_display_name text, p_pin text, p_timezone text default 'Asia/Kolkata')
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_id uuid;
begin
  if v_uid is null then
    raise exception 'Not authenticated' using errcode = '28000';
  end if;
  perform public._validate_pin(p_pin);
  if char_length(btrim(coalesce(p_display_name, ''))) not between 1 and 60 then
    raise exception 'Please enter your name' using errcode = '22023';
  end if;
  perform pg_advisory_xact_lock(hashtext('mealtrack.setup'));
  if exists (select 1 from public.households) then
    raise exception 'MealTrack is already set up. Sign in with your name and PIN.' using errcode = 'P0001';
  end if;

  insert into public.households (name, timezone, created_by)
  values (coalesce(nullif(btrim(p_name), ''), 'MealTrack'), coalesce(nullif(btrim(p_timezone), ''), 'Asia/Kolkata'), v_uid)
  returning id into v_id;

  insert into public.household_members (household_id, user_id, role, display_name, status, pin_hash)
  values (v_id, v_uid, 'admin', btrim(p_display_name), 'approved', extensions.crypt(p_pin, extensions.gen_salt('bf', 8)));

  return jsonb_build_object('id', v_id);
end;
$$;

-- ---------------------------------------------------------------------------
-- sign_in(name, pin, create):
--   known name + right PIN  -> this phone takes over that person (same role,
--                               same approval status); their old phone is signed out
--   known name + wrong PIN  -> {"ok": false, "error": "wrong_pin", "attempts_left": n}
--   unknown name, create=false -> {"ok": false, "error": "new_user"} (ask to confirm PIN)
--   unknown name, create=true  -> pending request for the admin
-- Wrong attempts are returned (not raised) so they are recorded.
-- ---------------------------------------------------------------------------
create or replace function public.sign_in(p_name text, p_pin text, p_create boolean default false)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_name text := btrim(coalesce(p_name, ''));
  v_key text := lower(btrim(coalesce(p_name, '')));
  v_household uuid;
  v_member record;
  v_existing text;
  v_fail record;
begin
  if v_uid is null then
    raise exception 'Not authenticated' using errcode = '28000';
  end if;
  select status into v_existing from public.household_members where user_id = v_uid;
  if v_existing is not null then
    return jsonb_build_object('ok', true, 'status', v_existing);
  end if;
  if char_length(v_name) not between 1 and 60 then
    raise exception 'Please enter your name' using errcode = '22023';
  end if;
  select id into v_household from public.households order by created_at limit 1;
  if v_household is null then
    raise exception 'MealTrack is not set up yet' using errcode = 'P0001';
  end if;

  perform pg_advisory_xact_lock(hashtext('mealtrack.signin'));
  select * into v_fail from public._pin_failures(v_key);
  if v_fail.for_name >= 5 or v_fail.overall >= 30 then
    return jsonb_build_object('ok', false, 'error', 'locked');
  end if;

  select user_id, status, pin_hash into v_member
    from public.household_members
   where household_id = v_household and lower(display_name) = v_key
   for update;

  if found then
    if v_member.pin_hash is null then
      return jsonb_build_object('ok', false, 'error', 'no_pin');
    end if;
    if v_member.pin_hash <> extensions.crypt(coalesce(p_pin, ''), v_member.pin_hash) then
      insert into public.family_pin_attempts (user_id, success, name_key) values (v_uid, false, v_key);
      return jsonb_build_object('ok', false, 'error', 'wrong_pin', 'attempts_left', greatest(0, 4 - v_fail.for_name));
    end if;
    insert into public.family_pin_attempts (user_id, success, name_key) values (v_uid, true, v_key);
    -- Move this person to the new phone. The previous phone loses access and its reminders.
    delete from public.push_subscriptions where user_id = v_member.user_id;
    delete from public.notification_preferences where user_id = v_member.user_id;
    update public.household_members set user_id = v_uid
     where household_id = v_household and user_id = v_member.user_id;
    return jsonb_build_object('ok', true, 'status', v_member.status, 'returning', true);
  end if;

  if not coalesce(p_create, false) then
    return jsonb_build_object('ok', false, 'error', 'new_user');
  end if;
  perform public._validate_pin(p_pin);
  if (select count(*) from public.household_members where household_id = v_household and status = 'pending') >= 10 then
    raise exception 'Too many sign-in requests are waiting. Ask the admin to review them first.' using errcode = 'P0001';
  end if;
  insert into public.household_members (household_id, user_id, role, display_name, status, pin_hash)
  values (v_household, v_uid, 'member', v_name, 'pending', extensions.crypt(p_pin, extensions.gen_salt('bf', 8)));
  return jsonb_build_object('ok', true, 'status', 'pending');
end;
$$;

-- ---------------------------------------------------------------------------
-- verify_my_pin: app-lock fallback (approved people only).
-- ---------------------------------------------------------------------------
create or replace function public.verify_my_pin(p_pin text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_row record;
  v_fail record;
begin
  select lower(display_name) as name_key, pin_hash into v_row
    from public.household_members where user_id = v_uid and status = 'approved';
  if not found then
    raise exception 'You are not signed in to MealTrack' using errcode = '42501';
  end if;
  perform pg_advisory_xact_lock(hashtext('mealtrack.signin'));
  select * into v_fail from public._pin_failures(v_row.name_key);
  if v_fail.for_name >= 5 then
    return jsonb_build_object('ok', false, 'error', 'locked');
  end if;
  if v_row.pin_hash is not null and v_row.pin_hash = extensions.crypt(coalesce(p_pin, ''), v_row.pin_hash) then
    insert into public.family_pin_attempts (user_id, success, name_key) values (v_uid, true, v_row.name_key);
    return jsonb_build_object('ok', true);
  end if;
  insert into public.family_pin_attempts (user_id, success, name_key) values (v_uid, false, v_row.name_key);
  return jsonb_build_object('ok', false, 'error', 'wrong_pin', 'attempts_left', greatest(0, 4 - v_fail.for_name));
end;
$$;

-- ---------------------------------------------------------------------------
-- change_my_pin: anyone approved. If they have no PIN yet (older accounts),
-- the current PIN is not required.
-- ---------------------------------------------------------------------------
create or replace function public.change_my_pin(p_current text, p_new text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_has_pin boolean;
  v_check jsonb;
begin
  select pin_hash is not null into v_has_pin
    from public.household_members where user_id = v_uid and status = 'approved';
  if not found then
    raise exception 'You are not signed in to MealTrack' using errcode = '42501';
  end if;
  perform public._validate_pin(p_new);
  if v_has_pin then
    v_check := public.verify_my_pin(p_current);
    if not (v_check ->> 'ok')::boolean then
      return v_check;
    end if;
  end if;
  update public.household_members
     set pin_hash = extensions.crypt(p_new, extensions.gen_salt('bf', 8))
   where user_id = v_uid;
  return jsonb_build_object('ok', true);
end;
$$;

-- Whether the signed-in person has a PIN yet (older accounts may not).
create or replace function public.i_have_pin()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce((select pin_hash is not null from public.household_members where user_id = auth.uid()), false);
$$;

-- ---------------------------------------------------------------------------
-- reset_member_pin: an admin sets a new PIN for someone who forgot theirs.
-- ---------------------------------------------------------------------------
create or replace function public.reset_member_pin(p_user_id uuid, p_new text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_household uuid := public.my_household_id();
  v_key text;
begin
  if v_household is null or not public.is_household_admin(v_household) then
    raise exception 'Only an admin can reset a PIN' using errcode = '42501';
  end if;
  perform public._validate_pin(p_new);
  update public.household_members
     set pin_hash = extensions.crypt(p_new, extensions.gen_salt('bf', 8))
   where household_id = v_household and user_id = p_user_id
  returning lower(display_name) into v_key;
  if v_key is null then
    raise exception 'Person not found' using errcode = 'P0002';
  end if;
  delete from public.family_pin_attempts where name_key = v_key; -- clear any lockout
end;
$$;

-- ---------------------------------------------------------------------------
-- admin_set_person_pin: SQL Editor only, e.g. if the only admin forgets their PIN.
--   select public.admin_set_person_pin('Reema', '123456');
-- ---------------------------------------------------------------------------
create or replace function public.admin_set_person_pin(p_name text, p_pin text)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_count int;
begin
  perform public._validate_pin(p_pin);
  update public.household_members
     set pin_hash = extensions.crypt(p_pin, extensions.gen_salt('bf', 8))
   where lower(display_name) = lower(btrim(p_name));
  get diagnostics v_count = row_count;
  delete from public.family_pin_attempts where name_key = lower(btrim(p_name));
  return v_count;
end;
$$;

-- Sign out no longer removes anyone; leave_household is only used to cancel a
-- pending request (and by approved people who really want to leave).

-- The shared family PIN is retired.
revoke execute on function public.join_with_pin(text, text) from authenticated;
revoke execute on function public.verify_family_pin(text) from authenticated;
revoke execute on function public.change_family_pin(text, text) from authenticated;
update public.households set pin_hash = null;

revoke execute on function
  public.sign_in(text, text, boolean),
  public.verify_my_pin(text),
  public.change_my_pin(text, text),
  public.i_have_pin(),
  public.reset_member_pin(uuid, text),
  public.admin_set_person_pin(text, text)
  from public, anon;

grant execute on function
  public.sign_in(text, text, boolean),
  public.verify_my_pin(text),
  public.change_my_pin(text, text),
  public.i_have_pin(),
  public.reset_member_pin(uuid, text)
  to authenticated;

revoke execute on function public.admin_set_person_pin(text, text) from authenticated;
